 plan.contract.verdict_decisive:\n                tried[-1].outcome, tried[-1].detail = \"weak\", f\"verdict {word or 'none'} does not decide\"\n                undecided.append((cand, doc, core, raw))\n                undecided_words.append(word or \"\")\n                if len(undecided) > MAX_WEAK_FALLBACKS:\n                    break\n                continue\n            decided_by = cand.endpoint[\"provider\"]\n        if options.confirm:\n            # A hit counts once ANOTHER provider returns the same value (one provider's two\n            # endpoints share a source). The earlier hit is the answer: it was the cheaper ask.\n            value = str(core.get(plan.contract.confirm) or \"\").strip().lower()\n            agreed = next((h for v, h in unconfirmed if v == value\n                           and h[0].endpoint[\"provider\"] != cand.endpoint[\"provider\"]), None)\n            if agreed is None:\n                unconfirmed.append((value, (cand, doc, core, raw)))\n                continue\n            confirmed_by = cand.endpoint[\"provider\"]\n            answers.append(agreed)\n            winner = agreed\n            break\n        answers.append((cand, doc, core, raw))\n        winner = (cand, doc, core, raw)\n        break\n    if winner is None and unconfirmed:\n        winner = unconfirmed[0][1]   # nobody agreed: the first hit, marked unconfirmed\n    if winner is None and undecided:\n        winner = undecided[0]        # nobody decided: the first answer, already paid for, marked undecided\n    if winner is None and best is not None:\n        winner = best[1]          # nobody cleared min_results — the fullest answer we paid for wins\n    if winner is None:\n        if tried and len(rate_waits) == len(tried):\n            wait = min(rate_waits)\n            _summarize(parent, tried_count=len(tried))\n            _audit_parent(parent, ep, 429, 0, audit_client)\n            raise GatewayFailed(\"provider_rate_limited\", status_code=429, detail={\n                \"error\": \"provider_rate_limited\", \"endpoint_id\": ep[\"id\"], \"retry_after_s\": wait,\n                \"tried\": [t.view() for t in tried],\n                \"message\": f\"every candidate for {ep['id']} is at treg's rate limit; nothing was \"\n                           f\"charged, try again in {wait} s\"}, retry_after_s=wait)\n        if team_busy and all(t.outcome == \"skipped\" for t in tried):\n            # Only treg's own busy refusals stopped the call: answer that, with its Retry-After,\n            # rather than a route_failed that blames the providers.\n            _summarize(parent, tried_count=len(tried))\n            _audit_parent(parent, ep, team_busy[-1].status_code, 0, audit_client)\n            raise team_busy[-1]\n        if admission_refusals and all(t.outcome == \"skipped\" for t in tried):\n            # Nothing ran: the refusal names a remedy, unlike a cost ceiling the caller may never have set.\n            _summarize(parent, tried_count=len(tried))\n            _audit_parent(parent, ep, 403, 0, audit_client)\n            raise admission.routed_refusal(ep[\"id\"], admission_refusals, [t.view() for t in tried])\n        if tried and all(t.outcome == \"skipped\" for t in tried):\n            raise ResolutionFailed(\"route_max_cost\", status_code=402, detail={\n                \"error\": \"route_max_cost\", \"endpoint_id\": ep[\"id\"],\n                \"max_cost_micro\": options.max_cost_micro, \"charged_micro\": spent,\n                \"tried\": [t.view() for t in tried],\n                \"message\": \"no candidate fits the remaining cost ceiling; nothing was charged\",\n            })\n        # One provider's failure does not turn the others' honest \"nobody\" into treg's 502: when at\n        # least one provider answered a miss, the call is a miss, marked `incomplete` when a\n        # provider on the way failed (its attempt says which), so a caller can ask again later.\n        # Only a call where no provider answered at all is `route_failed`.\n        outcome = \"miss\" if any(t.outcome == \"miss\" for t in tried) else \"error\"\n        incomplete = outcome == \"miss\" and any(t.outcome == \"error\" for t in tried)\n        if incomplete:\n            spent = _refund_errors(errored, pending, spent)\n        if outcome == \"miss\":\n            body_out = {\"output\": _empty_output(plan.contract), \"raw\": None,\n                        \"_treg\": {\"served_by\": None, \"outcome\": \"miss\", \"tried\": [t.view() for t in tried], \"charged_micro\": spent,\n                                  **({\"incomplete\": True} if incomplete else {}),\n                                  **({\"verification\": _unchecked(\"no_hit\")} if options.verify else {}),\n                                  **({\"capped\": True} if cost_capped else {}),\n                                  **({\"dropped\": plan.dropped} if plan.dropped else {})}}\n            # The event reads the empty answer the caller got, so its counts say 0 rather than\n            # nothing (`rows: 0` on a people search that found no one).\n            _summarize(parent, hit=False, tried_count=len(tried), output=body_out[\"output\"])\n            _audit_parent(parent, ep, 200, spent, audit_client)\n            headers = {\"X-Treg-Providers-Tried\": \",\".join(t.provider for t in tried), \"X-Treg-Route-Outcome\": \"miss\",\n                       **({\"X-Treg-Route-Incomplete\": \"true\"} if incomplete else {}),\n                       **({\"X-Treg-Route-Capped\": \"true\"} if cost_capped else {})}\n            return _json(body_out, 200, headers), spent\n        _summarize(parent, tried_count=len(tried))\n        _audit_parent(parent, ep, 502, 0, audit_client)   # a failed routed call charges nothing\n        raise GatewayFailed(\"route_failed\", status_code=502, detail={\n            \"error\": \"route_failed\", \"endpoint_id\": ep[\"id\"], \"tried\": [t.view() for t in tried], \"charged_micro\": spent,\n            \"dropped\": plan.dropped,\n            \"message\": f\"every candidate for {ep['id']} failed; nothing useful was charged\" if spent == 0 else\n                       f\"every candidate for {ep['id']} failed\"})\n    cand, doc, output, raw = winner\n    served = cand.endpoint[\"id\"]\n    winner_outcome = next(t.outcome for t in reversed(tried)\n                          if t.endpoint_id == served and t.outcome in (\"hit\", \"weak\", \"miss\"))\n    incomplete = False\n    if winner_outcome == \"miss\" and any(t.outcome == \"error\" for t in tried):\n        # The waterfall-off miss: the same rule as an all-miss walk (see the no-winner branch).\n        incomplete, spent = True, _refund_errors(errored, pending, spent)\n    upgrade, provider = None, cand.endpoint[\"provider\"]\n    if options.upgrade and winner_outcome == \"hit\" and not given.get(options.upgrade):\n        remaining = max(0, options.max_cost_micro - spent) if options.max_cost_micro is not None else None\n        upgrade, better, upgrade_cost = await _run_upgrade(parent, ep, options.upgrade, output, remaining,\n                                                           execute_child, upstream_client)\n        spent += upgrade_cost\n        if better is not None:\n            output, doc, served = better\n            provider = served.split(\".\")[0]\n    merged_from: list[str] = []\n    if options.merge and len(answers) > 1:\n        # A LIST answer is the only shape a union makes sense for, and the caller has already been\n        # charged for every attempt (`charged_micro` is the running sum) - so without this the\n        # router throws away rows the team paid for.\n        field = _list_field(plan.contract)\n        if field:\n            rows = _merge_rows(field, answers, plan.identity.get(\"limit\"))\n            contributed = [c.endpoint[\"id\"] for c, _, core_i, _ in answers if (core_i.get(field) or [])]\n            # The deduped union in attempt order whenever two providers contributed: an earlier\n            # provider's row for the same person (with its details) leads, and a later provider's\n            # own repeats count once, however many rows it returned.\n            if len(contributed) > 1:\n                output = {**output, field: rows}\n                if \"count\" in plan.contract.output:\n                    output[\"count\"] = len(rows)\n                merged_from = contributed\n                served = merged_from[0]\n    # Holders of the asked role now first, past holders last (`row.rank_by_role`), merged or not.\n    if plan.contract.row_rank and output and isinstance(output.get(plan.contract.row_of), list):\n        output = {**output, plan.contract.row_of: plan.contract.rank_rows(plan.identity, output[plan.contract.row_of])}\n    # Every provider whose rows are in the answer: a merged row from one that ignored a filter\n    # answers the looser question too.\n    ignored = list(dict.fromkeys(k for c, _, core_i, _ in answers\n                                 if c.endpoint[\"id\"] in merged_from for k in c.ignored)) if merged_from else list(cand.ignored)\n    # The rows answer a LOOSER question than the caller asked when the winner could not express a\n    # filter. It is on the attempt, but no caller reads `tried[]` — say it where the answer is, and\n    # on a header, or the agent post-filters nothing and never knows why the geography is wrong.\n    # A found contact is not a confirmed one. When the contract says so and the provider did not\n    # vouch for deliverability (`verified` absent or false — Hunter's `accept_all`, LeadMagic's\n    # personal finder, every phone provider), say it where the agent reads the answer. A\n    # suggestion only, unless the caller sent `X-Treg-Route-Verify`: then the check runs below.\n    advice = (plan.contract.advice_unverified\n              if plan.contract.advice_unverified and output and output.get(\"verified\") is not True else \"\")\n    advice_locked = False  # a check's disagree/skip advice wins over domain-mismatch advice\n    verification = None\n    check = plan.contract.check\n    if options.verify and check is not None and winner_outcome in (\"hit\", \"weak\"):\n        # The find's holds stay open in `pending` while the check runs: a cancellation releases\n        # them with everything else, and `run_routed` still closes each exactly once.\n        remaining = max(0, options.max_cost_micro - spent) if options.max_cost_micro is not None else None\n        verification, check_cost = await _run_check(parent, check, output, remaining,\n                                                    pending, execute_child, upstream_client)\n        spent += check_cost\n        if verification[\"checked\"]:\n            advice = \"\"   # the verdict answers what the advice suggests\n            if (check.disagree_advice and output.get(\"verified\") is True and not verification.get(\"pending\")\n                    and verification[\"verdict\"] != \"valid\"):\n                advice = check.disagree_advice   # the check wins; say so where the claim is read\n                advice_locked = True\n        elif check.skip_advice and verification[\"reason\"] == check.skip_reason:\n            advice = check.skip_advice   # the caller asked; say why this hit was not checked\n            advice_locked = True\n    elif options.verify:\n        verification = _unchecked(\"no_hit\")   # a miss is never checked; say why\n    # Disclose whether the hit's mailbox domain matches the domain the caller sent. Never alter\n    # the answer: a LinkedIn-only child that returns a former employer is still a billed hit.\n    domain_match = (_email_domain_match(plan.identity, output)\n                    if winner_outcome in (\"hit\", \"weak\") else None)\n    if (domain_match is False and plan.contract.advice_domain_mismatch and not advice_locked):\n        advice = plan.contract.advice_domain_mismatch\n    confirmation = ({\"field\": plan.contract.confirm, \"confirmed\": confirmed_by is not None, \"confirmed_by\": confirmed_by}\n                    if options.confirm and winner_outcome in (\"hit\", \"weak\") else None)\n    decision = ({\"decided\": decided_by is not None, \"decided_by\": decided_by,\n                 \"ordered_by\": \"quality\" if ordered_on and quality else \"price\"}\n                if options.decisive and winner_outcome in (\"hit\", \"weak\") else None)\n    # A child (or a merge) that answers more rows than the caller's sent `limit` still returns\n    # every billed row: routed endpoints wrap the child's answer and never alter it. Disclose the\n    # excess on `_treg` (and a header) instead of trimming. Only a limit the caller SENT counts —\n    # a contract default is not a question anyone asked.\n    limit_exceeded = None\n    asked_limit = plan.identity.get(\"limit\")\n    if (isinstance(given, dict) and \"limit\" in given\n            and isinstance(asked_limit, (int, float)) and not isinstance(asked_limit, bool)):\n        list_field = _list_field(plan.contract)\n        returned_n = len((output or {}).get(list_field) or []) if list_field else 0\n        asked_n = int(asked_limit)\n        if list_field and returned_n > asked_n:\n            limit_exceeded = _limit_exceeded_note(\n                asked=asked_n, returned=returned_n, served_by=served,\n                merged=bool(merged_from), adapter=cand.adapter)\n\n    output, long_cursor = _long_cursor(output, cand.adapter, bool(merged_from))\n\n    body_out = {\"output\": output or _empty_output(plan.contract), \"raw\": doc,\n                \"_treg\": {\"served_by\": served, \"provider\": provider, \"tier\": cand.tier,\n                          **({\"merged_from\": merged_from} if merged_from else {}),\n                          **({\"next_cursor\": long_cursor} if long_cursor else {}),\n                          **({\"advice\": advice} if advice else {}),\n                          **({\"domain_match\": domain_match} if domain_match is not None else {}),\n                          \"outcome\": winner_outcome, \"tried\": [t.view() for t in tried], \"charged_micro\": spent,\n                          **({\"incomplete\": True} if incomplete else {}),\n                          **({\"verification\": verification} if verification is not None else {}),\n                          **({\"confirmation\": confirmation} if confirmation is not None else {}),\n                          **({\"decision\": decision} if decision is not None else {}),\n                          **({\"upgrade\": upgrade} if upgrade is not None else {}),\n                          **({\"ordered_by\": \"quality\" if ordered_on and quality else \"price\"} if options.quality else {}),\n                          **({\"capped\": True} if cost_capped else {}),\n                          **({\"ignored_filters\": ignored} if ignored else {}),\n                          **({\"limit_exceeded\": limit_exceeded} if limit_exceeded else {}),\n                          **({\"dropped\": plan.dropped} if plan.dropped else {})}}\n    _summarize(parent, served_by=served, tried_count=len(tried), output=body_out[\"output\"],\n               hit={\"hit\": True, \"weak\": True, \"miss\": False}.get(winner_outcome),\n               check_verdict=(verification or {}).get(\"verdict\")\n               if (verification or {}).get(\"checked\") else None)\n    _audit_parent(parent, ep, 200, spent, audit_client)\n    return _json(body_out, 200, {\"X-Treg-Served-By\": served, \"X-Treg-Providers-Tried\": \",\".join(t.provider for t in tried),\n                                 **({\"X-Treg-Merged-From\": \",\".join(merged_from)} if merged_from else {}),\n                                 **({\"X-Treg-Ignored-Filters\": \",\".join(ignored)} if ignored else {}),\n                                 **({\"X-Treg-Limit-Exceeded\":\n                                     f\"asked={limit_exceeded['asked']},returned={limit_exceeded['returned']}\"}\n                                    if limit_exceeded else {}),\n                                 **({\"X-Treg-Domain-Match\": str(domain_match).lower()} if domain_match is not None else {}),\n                                 **({\"X-Treg-Route-Capped\": \"true\"} if cost_capped else {}),\n                                 **({\"X-Treg-Route-Incomplete\": \"true\"} if incomplete else {}),\n                                 **({\"X-Treg-Route-Confirmed\": str(confirmation[\"confirmed\"]).lower()} if confirmation else {}),\n                                 **({\"X-Treg-Route-Decided\": str(decision[\"decided\"]).lower()} if decision else {}),\n                                 **({\"X-Treg-Route-Upgraded\": str(upgrade[\"upgraded\"]).lower()} if upgrade else {}),\n                                 \"X-Treg-Route-Outcome\": winner_outcome}), spent\n\n\n_CHECK_REASONS = {\"route_max_cost\": \"over_cost_limit\", \"route_no_candidate\": \"no_checker\",\n                  **{k: \"spend_limit\" for k in _GLOBAL_REFUSALS},\n                  **{k: \"not_allowed\" for k in _CANDIDATE_LOCAL_FAILURES},\n                  \"org_endpoint_quota_exceeded\": \"quota_exceeded\", \"admission_denied\": \"not_allowed\"}\n\n\ndef _unchecked(reason: str) -> dict:\n    return {\"verdict\": \"unknown\", \"checked\": False, \"served_by\": None, \"cost_micro\": 0, \"reason\": reason}\n\n\nasync def _run_check(parent: CallContext, check, output: dict, remaining: int | None, pending: list,\n                     execute_child, upstream_client) -> tuple[dict, int]:\n    \"\"\"The contract's check on a hit, as an ordinary call: (`_treg.verification`, money it moved).\n\n    A routed check (`treg.people.email.verify`) runs its own waterfall and closes its own holds;\n    a direct one leaves its hold in the find's `pending`. Either way the caller's own key comes\n    first, its limits and access rules apply, and a failure costs the find nothing: no check ran.\"\"\"\n    cat = catalog_store.load()\n    ep = cat.by_id.get(check.endpoint)\n    value = output.get(check.field)\n    if ep is None or not isinstance(value, str) or not value.strip():\n        return _unchecked(\"no_checker\"), 0\n    if check.when and not P.evaluate(check.when, {check.field: value}):\n        return _unchecked(check.skip_reason), 0\n    routed = ep.get(\"kind\") == \"routed\"\n    if routed:\n        query, body = {}, {check.field: value}\n    else:\n        adapter = cat.adapters.get(ep[\"id\"])\n        contract = cat.contracts.get(ep.get(\"capability\"))\n        if adapter is None or not adapter.verified or contract is None:\n            return _unchecked(\"no_checker\"), 0\n        identity, variant = canonical_identity(contract, {check.field: value})\n        if variant is None:\n            return _unchecked(\"no_checker\"), 0\n        query, body = adapter.to_upstream(identity, variant)\n    prefer = ((PREFER_HEADER.encode(), \",\".join(check.prefer).encode()),) if routed and check.prefer else ()\n    child = CallContext(input=_child_input(parent, ep, query, body, remaining, prefer),\n                        call_ref=f\"{parent.call_ref}:v\", meta=parent.meta,\n                        deferred_settles=None if routed else pending,\n                        quota_admissions=parent.quota_admissions,\n                        quota_pending=parent.quota_pending)\n    try:\n        response = await execute_child(child, upstream_client)\n        raw = await _read(response)\n    except CallFailure as exc:\n        return _unchecked(_CHECK_REASONS.get(exc.kind, \"checker_failed\")), 0\n    except Exception:\n        log.warning(\"check %s failed after %s\", check.endpoint, parent.call_ref, exc_info=True)\n        return _unchecked(\"checker_failed\"), 0\n    try:\n        doc = json.loads(raw)\n    except ValueError:\n        doc = None\n    if routed:\n        meta = (doc.get(\"_treg\") or {}) if isinstance(doc, dict) else {}\n        if response.status == 202 and meta.get(\"outcome\") == \"pending\":\n            # Still running after the routed wait (BounceBan `verifying`): its hold stays with the\n            # async worker, which settles or releases it; nothing of it is charged now.\n            # Forward the child's async poll descriptor so the caller can resume without digging\n            # through GET /calls/{call_id}; cost_micro is the hold (reserved), not a settled charge.\n            view = {\"verdict\": \"unknown\", \"checked\": True, \"served_by\": meta.get(\"served_by\"),\n                    \"cost_micro\": int(meta.get(\"reserved_micro\") or 0), \"pending\": True,\n                    \"call_id\": meta.get(\"call_ref\")}\n            if isinstance(meta.get(\"async\"), dict):\n                view[\"async\"] = meta[\"async\"]\n            return view, 0\n        cost = int(_header(response, \"X-Treg-Cost-Micro\") or 0)\n        served = meta.get(\"served_by\")\n        if not 200 <= response.status < 300 or meta.get(\"outcome\") not in (\"hit\", \"weak\", \"miss\"):\n            return {**_unchecked(\"checker_failed\"), \"cost_micro\": cost}, cost\n        word = (catalog_results.verdict(served, 200, json.dumps(doc.get(\"raw\")).encode())\n                if served and meta.get(\"outcome\") != \"miss\" else None)\n        return {\"verdict\": word or \"unknown\", \"checked\": True, \"served_by\": served, \"cost_micro\": cost}, cost\n    cost = int(_header(response, \"X-Treg-Cost-Micro\") or 0)\n    adapter = cat.adapters[ep[\"id\"]]\n    try:\n        missed = doc is None or adapter.is_miss(doc)\n    except Exception:  # noqa: BLE001 - an unreadable answer is a failed check\n        missed = True\n    if not 200 <= response.status < 300 or missed:\n        return {**_unchecked(\"checker_failed\"), \"cost_micro\": cost}, cost\n    word = catalog_results.verdict(ep[\"id\"], response.status, raw)\n    return {\"verdict\": word or \"unknown\", \"checked\": True, \"served_by\": ep[\"id\"], \"cost_micro\": cost}, cost\n\n\ndef _name_key(name) -> str | None:\n    \"\"\"First initial and last word, folded: `Bill Gates` and `William H. Gates` are one person's name.\"\"\"\n    words = re.sub(r\"[^a-z ]+\", \" \", unicodedata.normalize(\"NFKD\", name).encode(\"ascii\", \"ignore\").decode().lower()).split() \\\n        if isinstance(name, str) else []\n    return f\"{words[0][0]}|{words[-1]}\" if len(words) >= 2 else None\n\n\nasync def _run_upgrade(parent: CallContext, ep: dict, key: str, output: dict, remaining: int | None,\n                       execute_child, upstream_client) -> tuple[dict, tuple | None, int]:\n    \"\"\"`X-Treg-Route-Upgrade`: the hit named a stronger identity (a LinkedIn URL for an email), so ask\n    this same routed endpoint again by that key alone, its providers in order of measured quality.\n    Its answer replaces the first only when it is a hit about the same person (the contract's name\n    agrees); otherwise the first, already-paid answer stands. Returns (`_treg.upgrade`, the\n    replacing (output, raw, served_by) or None, money it moved). A failure costs the first answer nothing.\"\"\"\n    value = output.get(key)\n    if not isinstance(value, str) or not value.strip():\n        return {\"upgraded\": False, \"via\": key, \"reason\": f\"no_{key}\"}, None, 0\n    child = CallContext(input=_child_input(parent, ep, {}, {key: value}, remaining, ((QUALITY_HEADER.encode(), b\"1\"),)),\n                        call_ref=f\"{parent.call_ref}:u\", meta=parent.meta, deferred_settles=None)\n    try:\n        response = await execute_child(child, upstream_client)\n        doc = json.loads(await _read(response))\n    except CallFailure as exc:\n        return {\"upgraded\": False, \"via\": key, \"reason\": exc.kind}, None, 0\n    except Exception:\n        log.warning(\"upgrade by %s failed after %s\", key, parent.call_ref, exc_info=True)\n        return {\"upgraded\": False, \"via\": key, \"reason\": \"failed\"}, None, 0\n    cost = int(_header(response, \"X-Treg-Cost-Micro\") or 0)\n    meta = (doc.get(\"_treg\") or {}) if isinstance(doc, dict) else {}\n    view = {\"via\": key, \"served_by\": meta.get(\"served_by\"), \"cost_micro\": cost}\n    if not 200 <= response.status < 300 or meta.get(\"outcome\") != \"hit\":\n        return {**view, \"upgraded\": False, \"reason\": \"no_hit\"}, None, cost\n    found = doc.get(\"output\") or {}\n    if \"full_name\" in output and _name_key(found.get(\"full_name\")) != _name_key(output.get(\"full_name\")):\n        return {**view, \"upgraded\": False, \"reason\": \"other_name\"}, None, cost\n    return {**view, \"upgraded\": True}, ({**output, **{k: v for k, v in found.items() if v is not None}},\n                                        doc.get(\"raw\"), meta.get(\"served_by\")), cost\n\n\ndef _note_call(parent: CallContext, plan: Plan, cand: Candidate, child: CallContext, tried: list) -> None:\n    \"\"\"Which order each provider actually reached came from. `route_order` names the first's;\n    `route_retry_order` the first later one the contract's own order would not have reached next.\n    A child counts only when its request left for the provider or its archived answer was served\n    (`reached_provider`), never when a local gate refused it. Each order is read from its first\n    candidate not yet passed over, and every earlier attempt is passed over, reached or not.\"\"\"\n    if not child.reached_provider:\n        return\n    route = dict((parent.route_summary or {}).get(\"route_rule\") or {})\n    passed = {t.endpoint_id for t in tried}\n    called = cand.endpoint[\"id\"]\n\n    def next_in(order: str) -> str | None:\n        return next((e for e in plan.orders.get(order, ()) if e not in passed), None)\n    if not plan.orders:\n        source = \"header\"  # the caller's own X-Treg-Route-Prefer order\n    else:\n        source = \"default\" if called == next_in(\"default\") else \"rule\" if called == next_in(\"rule\") else \"quality\"\n    if \"route_order\" not in route:\n        route[\"route_order\"] = source\n    elif source not in (\"default\", \"header\") and \"route_retry_order\" not in route:\n        route[\"route_retry_order\"] = source\n    else:\n        return\n    _summarize(parent, route_rule=route)\n\n\ndef _summarize(parent: CallContext, **outcome) -> None:\n    \"\"\"What the router decided, for the parent's call event (service.py `_routed_event`).\"\"\"\n    parent.route_summary = {**(parent.route_summary or {}), **outcome}\n\n\ndef _audit_parent(parent: CallContext, ep: dict, status: int, charged: int, client: str) -> None:\n    c = parent.input.caller\n    audit.record_call(org_id=c.org_id, user_email=c.email, tool_name=ep[\"id\"], method=\"POST\", path=ep[\"path\"],\n                      status_code=status, client=client,\n                      api_key_id=c.api_key_id, api_key_name=c.api_key_name,\n                      api_key_prefix=c.api_key_prefix,\n                      # The tag columns too: a pinned caller's history is filtered on them, so a\n                      # routed parent row without its pin would hide the caller's own call.\n                      telemetry={\"call_ref\": parent.call_ref, \"endpoint_id\": ep[\"id\"], \"provider\": \"treg\",\n                                 \"credential_tier\": \"routed\", \"cost_charged_micro\": charged,\n                                 **_tag_telemetry(parent.meta)})\n\n\ndef _json(value, status: int, headers: dict[str, str]) -> UpstreamResponse:\n    body = jsontext.dumps_bytes(value, separators=(\",\", \":\"))\n\n    async def _one():\n        yield body\n\n    async def _closed():\n        return None\n    raw = [(b\"content-length\", str(len(body)).encode()), (b\"content-type\", b\"application/json\")]\n    raw += [(k.lower().encode(\"latin-1\"), v.encode(\"latin-1\")) for k, v in headers.items()]\n    return UpstreamResponse(status, tuple(raw), _one(), _closed)\n"
    },
    {
      "path": "src/treg/application/call/idempotency.py",
      "content": "\"\"\"Idempotency state for proxied calls.\"\"\"\n\nfrom __future__ import annotations\n\nimport asyncio\nimport hashlib\nimport json\nimport logging\nfrom dataclasses import dataclass\nfrom datetime import datetime, timedelta, timezone\nfrom typing import TYPE_CHECKING\n\nfrom sqlalchemy import delete, func, or_, text, update\nfrom sqlalchemy.exc import IntegrityError, TimeoutError as PoolTimeoutError\nfrom sqlalchemy.ext.asyncio import AsyncSession\nfrom sqlmodel import select\n\nfrom ... import archive\nfrom ...config import get_settings\nfrom ...infra.db import session_maker\nfrom ...domain.identity.access import Caller\nfrom ...models import AsyncTaskRecord, CallRecord, Hold, IdempotentCall, LedgerEntry\nfrom .types import IdempotencyFailed, IdempotentReplay\n\nif TYPE_CHECKING:\n    from .intake import CallMeta\n\n\nIDEMPOTENCY_WINDOW_S = 24 * 3600   # retries happen in seconds; a day is generous and easy to reason about\nIDEMPOTENCY_HEADER = \"idempotency-key\"\nIDEMPOTENCY_SWEEP_BATCH = 100  # expired labels one claim reclaims; the rest go with later calls\n# A pending claim is a LEASE owned by one call (`call_ref`). The owner renews it every\n# IDEMPOTENCY_LEASE_RENEW_S while it runs (`_hold_claim_lease`), so `created_at` older than\n# IDEMPOTENCY_STALE_PENDING_S means the owner stopped: its process died, or the bookkeeping that\n# marks the claim done or releases it failed (a pool timeout). Such a claim is closed with a stored\n# terminal answer rather than answering 409 for the whole window; see `_resolve_stale_claim`.\nIDEMPOTENCY_LEASE_RENEW_S = 5 * 60\nIDEMPOTENCY_STALE_PENDING_S = 3 * IDEMPOTENCY_LEASE_RENEW_S\n_POOL_RETRY_PAUSE_S = 0.5  # the settle retry's pause (settle.py); one retry, fresh session\n\n_IDEM_MAX_KEY = 200\n\n\ndef _idempotency_key(raw_header: str | None) -> str:\n    \"\"\"The caller's label for this request, or \"\" when they sent none.\n\n    Only ever the client's. A server-invented key — hashing the URL and body, say — would silently\n    collapse two calls a caller genuinely MEANT to make twice, and \"do this again\" is a legitimate\n    thing to ask of an API. No header means today's behaviour exactly: no lookup, no storage.\n    \"\"\"\n    return (raw_header or \"\").strip()[:_IDEM_MAX_KEY]\n\n\n_IDEM_SCOPE_SEP = \"\\x1f\"\n\n\ndef _scoped_idempotency_key(\n    key: str, meta: CallMeta, *, pinned_tags: dict | None = None,\n) -> str:\n    \"\"\"The caller's label, PARTITIONED by the primary tag.\n\n    A reselling builder runs every one of their users through one token, so two of them will both\n    reach for `retry-1` — and `IdempotentCall` is unique on (membership_id, key), which would serve\n    the second user the FIRST one's stored response body. That is the cross-tenant leak the table was\n    built to prevent, reappearing one level down.\n\n    Folding the value into the stored key partitions retries exactly as widening the unique constraint\n    would, with no migration: `uq_idem_caller_key` is declared in `__table_args__`, so SQLAlchemy emits\n    it as a table CONSTRAINT inside CREATE TABLE — Postgres could drop it, sqlite could not without\n    rebuilding the table. Every access site keeps querying by (membership_id, key) and simply receives\n    this value.\n\n    The primary caller-asserted dimension still partitions unpinned callers. An enforced pin is\n    additionally part of the namespace: changing any pin must not expose an earlier cached body.\n    \"\"\"\n    if not key:\n        return key\n    scoped = f\"{meta.primary_val}{_IDEM_SCOPE_SEP}{key}\" if meta.primary_val else key\n    if pinned_tags:\n        pins = json.dumps(pinned_tags, sort_keys=True, separators=(\",\", \":\"))\n        return f\"pins:{pins}{_IDEM_SCOPE_SEP}{scoped}\"\n    return scoped\n\n\ndef _idem_display(key: str) -> str:\n    \"\"\"The label as the CALLER wrote it — error messages must not echo our internal scoping.\"\"\"\n    return key.rsplit(_IDEM_SCOPE_SEP, 1)[-1]\n\n\ndef _request_fingerprint(method: str, rest: str, body: bytes, query: str = \"\") -> str:\n    \"\"\"What the label was used FOR, so reusing it on a different request can be caught.\n\n    A client that reuses one label for two different requests has a bug. Quietly returning the first\n    answer would hide it, and the caller would be left wondering why their second call returned\n    somebody else's data. Refusing loudly is the useful behaviour, and it is what Stripe does.\n\n    The QUERY STRING is part of the request. It was missing here at first, and since most catalog\n    calls are GETs that carry all their arguments in the query, that made the check almost inert: two\n    genuinely different lookups under one label matched, and the second was answered with the first\n    one's data instead of the 422 this function exists to raise.\n    \"\"\"\n    h = hashlib.sha256()\n    h.update(method.upper().encode())\n    h.update(b\"\\0\")\n    h.update(rest.encode())\n    h.update(b\"\\0\")\n    h.update((query or \"\").encode())\n    h.update(b\"\\0\")\n    h.update(body or b\"\")\n    return h.hexdigest()\n\n\nasync def _replay_idempotent(key: str, fingerprint: str, caller: Caller,\n                             db: AsyncSession) -> IdempotentReplay | None:\n    \"\"\"The stored answer for this caller's label, or None if there is nothing to replay.\n\n    Returns a real response, so the provider is never reached and no money moves. That is the whole\n    point: merely skipping the second CHARGE would still make the second upstream call, which means\n    still paying the provider and simply absorbing the double cost ourselves.\n    \"\"\"\n    row = (await db.execute(select(IdempotentCall).where(\n        IdempotentCall.membership_id == caller.membership.id,\n        IdempotentCall.key == key))).scalar_one_or_none()\n    if row is None:\n        return None\n    if row.expires_at < datetime.now(timezone.utc).replace(tzinfo=None):\n        # Past its window: the label is free again, and the call proceeds normally.\n        await db.delete(row)\n        await db.commit()\n        return None\n    if row.request_fingerprint and row.request_fingerprint != fingerprint:\n        raise IdempotencyFailed(\n            \"idempotency_mismatch\", status_code=422,\n            detail=(f\"Idempotency-Key {_idem_display(key)!r} was already used for a different request. Use a new key, or \"\n                    f\"repeat the original request exactly.\"))\n    if (row.status != \"done\" and row.call_ref\n            and row.created_at < _utcnow() - timedelta(seconds=IDEMPOTENCY_STALE_PENDING_S)):\n        resolved = await _resolve_stale_claim(row, caller, db)\n        if resolved is not None:\n            return resolved\n    if row.status != \"done\" or row.response_status is None:\n        # Still in flight. The first call is talking to the provider right now; telling the caller to\n        # retry is honest and cheap, and it is what stops the second one duplicating the spend.\n        raise IdempotencyFailed(\n            \"idempotency_in_progress\", status_code=409,\n            detail=(f\"a call with Idempotency-Key {_idem_display(key)!r} \"\n                    \"is still in progress — retry shortly\"))\n    # A trimmed row names its archive entry instead of carrying bytes. Not read here: this runs\n    # inside the request's session, and the read can go to object storage.\n    trimmed = row.response_body is None and bool(row.archive_content_hash)\n    return IdempotentReplay(\n        body=row.response_body or b\"\",\n        archive=(row.archive_key_hash or \"\", row.archive_content_hash or \"\") if trimmed else None,\n        status_code=row.response_status,\n        media_type=row.response_media_type or \"application/json\",\n        charged_micro=row.charged_micro,\n        # The ORIGINAL call's id: a retry must resolve to the row that actually holds the\n        # money, not to a fresh reference for work that never happened.\n        call_ref=row.call_ref or \"\",\n    )\n\n\ndef _utcnow() -> datetime:\n    return datetime.now(timezone.utc).replace(tzinfo=None)\n\n\ndef _owned(membership_id: int, key: str, call_ref: str):\n    \"\"\"The WHERE clause every owner write carries: a claim taken over by another call is not ours.\"\"\"\n    return (IdempotentCall.membership_id == membership_id, IdempotentCall.key == key,\n            IdempotentCall.call_ref == call_ref)\n\n\nasync def _money_of(db: AsyncSession, org_id: int, call_ref: str, since: datetime,\n                    until: datetime) -> dict:\n    \"\"\"What one call and every child it spawned did with money, from the hold and ledger tables.\n\n    A call's money lives under ids prefixed by its call_ref: its own hold, `:overflow`, routed\n    children `:r{n}` and their polls, hub steps `:s{n}` and the hub `:price`. uuid hex carries no\n    LIKE wildcard. The LIKE cannot use an index under a non-C collation, so the ledger read is\n    bounded to the owner's lifetime on `(org_id, created_at)`: from the claim to one renewal past\n    its last lease renewal. The only money that can move after that is an async task's worker\n    settling or releasing it, so the tasks the owner started in its lifetime are found the same\n    way and their ledger rows read by exact call id, with no time bound: a still-pending task is\n    money in flight, and a late settle is a charge.\n    \"\"\"\n    def mine(col):\n        return or_(col == call_ref, col.like(f\"{call_ref}:%\"))\n    open_hold = (await db.execute(select(Hold.id).where(\n        Hold.org_id == org_id, mine(Hold.id)).limit(1))).first() is not None\n    rows = list((await db.execute(select(LedgerEntry.kind, LedgerEntry.amount_micro).where(\n        LedgerEntry.org_id == org_id, LedgerEntry.created_at >= since, LedgerEntry.created_at <= until,\n        mine(LedgerEntry.call_id)))).all())\n    tasks = (await db.execute(select(AsyncTaskRecord.call_id, AsyncTaskRecord.status).where(\n        AsyncTaskRecord.org_id == org_id, AsyncTaskRecord.created_at >= since,\n        AsyncTaskRecord.created_at <= until, mine(AsyncTaskRecord.call_id)))).all()\n    if any(status == \"pending\" for _, status in tasks):\n        open_hold = True  # a task's hold is its worker's until it resolves\n    if tasks:\n        rows += (await db.execute(select(LedgerEntry.kind, LedgerEntry.amount_micro).where(\n            LedgerEntry.call_id.in_([task_id for task_id, _ in tasks]),\n            LedgerEntry.created_at > until))).all()\n    # settle entries are negative (money leaving)\n    return {\"in_flight\": open_hold, \"charged\": -sum(amount for kind, amount in rows if kind == \"settle\")}\n\n\nasync def _resolve_stale_claim(row: IdempotentCall, caller: Caller, db: AsyncSession):\n    \"\"\"Close an abandoned lease with a stored terminal answer; never run the key again.\n\n    An open hold or a pending async task means the owner or its worker is not done: 409 (None\n    here). Otherwise the answer is a stored 410, so every later retry gets the same reply:\n    `idempotency_response_lost` with the charge when the owner's money shows one (the answer was\n    paid for but not kept), else `idempotency_outcome_unknown`. The claim is never handed to a new\n    call: a lease that stopped renewing does not prove its owner stopped, and a second run under\n    the same key is exactly the double charge this table exists to prevent. A new key calls again.\n\n    The write is a compare-and-swap on the lease as read (owner AND `created_at`): a renewal or\n    another retry in between wins, and this one answers 409 on the fresh state.\n    \"\"\"\n    started = row.expires_at - timedelta(seconds=IDEMPOTENCY_WINDOW_S)\n    lifetime_end = row.created_at + timedelta(seconds=IDEMPOTENCY_LEASE_RENEW_S + 60)\n    money = await _money_of(db, caller.org_id, row.call_ref, started, lifetime_end)\n    if money[\"in_flight\"]:\n        return None\n    label, owner, charged = _idem_display(row.key), row.call_ref, max(0, money[\"charged\"])\n    if charged:\n        detail = {\"error\": \"idempotency_response_lost\", \"call_id\": owner, \"charged_micro\": charged,\n                  \"message\": (f\"the call with Idempotency-Key {label!r} completed and was charged, but \"\n                              f\"its response was not retained. GET /calls/{owner}/result may still \"\n                              \"have it; send a new key to call again.\")}\n    else:\n        detail = {\"error\": \"idempotency_outcome_unknown\", \"call_id\": owner,\n                  \"message\": (f\"the call with Idempotency-Key {label!r} stopped before its outcome was \"\n                              f\"recorded and may have reached the provider. GET /calls/{owner} shows \"\n                              \"what it cost; send a new key to call again.\")}\n    body = json.dumps({\"detail\": detail}, separators=(\",\", \":\")).encode()\n    won = (await db.execute(update(IdempotentCall).where(\n        IdempotentCall.id == row.id, IdempotentCall.status == \"pending\",\n        IdempotentCall.call_ref == owner, IdempotentCall.created_at == row.created_at,\n    ).values(status=\"done\", response_status=410, response_body=body,\n             response_media_type=\"application/json\", charged_micro=charged,\n    # A lost swap must not paint the loaded row as done: the caller re-reads it as a 409.\n    ).execution_options(synchronize_session=False))).rowcount == 1\n    await db.commit()\n    if not won:\n        return None\n    logging.getLogger(\"treg.idempotency\").warning(\n        \"idempotency claim %s: owner %s abandoned it; stored 410 %s\", label, owner, detail[\"error\"])\n    return IdempotentReplay(body=body, status_code=410, media_type=\"application/json\",\n                            charged_micro=charged, call_ref=owner)\n\n\nasync def _with_pool_retry(work):\n    \"\"\"One retry after a pool timeout, on a fresh session: the settle retry's shape. A saturated\n    pool is the usual reason bookkeeping fails, and a failed write here strands a claim.\"\"\"\n    try:\n        return await work()\n    except PoolTimeoutError:\n        await asyncio.sleep(_POOL_RETRY_PAUSE_S)\n        return await work()\n\n\nasync def _renew_claim_lease(claim: tuple[int, str, str]) -> None:\n    \"\"\"Refresh the owner's lease. Never raises: a missed renewal only shortens the lease.\"\"\"\n    membership_id, key, call_ref = claim\n\n    async def _renew() -> None:\n        async with session_maker() as db:\n            await db.execute(update(IdempotentCall).where(\n                *_owned(membership_id, key, call_ref), IdempotentCall.status == \"pending\",\n            ).values(created_at=_utcnow()))\n            await db.commit()\n\n    try:\n        await _with_pool_retry(_renew)\n    except Exception as exc:  # noqa: BLE001\n        logging.getLogger(\"treg.idempotency\").warning(\n            \"could not renew idempotency claim %s: %s\", _idem_display(key), exc)\n\n\nasync def _hold_claim_lease(state) -> None:\n    \"\"\"Renew `state.idem_claim` until the request drops it; the caller cancels this task on exit.\"\"\"\n    while True:\n        await asyncio.sleep(IDEMPOTENCY_LEASE_RENEW_S)\n        claim = getattr(state, \"idem_claim\", None)\n        if not claim:\n            return\n        await _renew_claim_lease(claim)\n\n\nasync def resolve_archived_replay(replay: IdempotentReplay, key: str) -> IdempotentReplay:\n    \"\"\"A trimmed row's answer, read back from the archive (hash-checked there). Call it with NO\n    session held: `archive.answer_bytes` takes its own short session, then reads object storage.\n    When the bytes are gone the answer is the same 410 as an answer never kept; the key is not run\n    again, which would be a second charge. Never raises.\"\"\"\n    if replay.archive is None:\n        return replay\n    try:\n        body = await archive.answer_bytes(*replay.archive)\n    except Exception:  # a failed read is the 410 below, never a 500\n        logging.getLogger(\"treg.idempotency\").warning(\n            \"idempotency %s: archived answer unreadable\", _idem_display(key), exc_info=True)\n        body = None\n    if body is not None:\n        return IdempotentReplay(body=body, status_code=replay.status_code, media_type=replay.media_type,\n                                charged_micro=replay.charged_micro, call_ref=replay.call_ref)\n    detail = {\"error\": \"idempotency_response_lost\", \"call_id\": replay.call_ref,\n              \"charged_micro\": replay.charged_micro,\n              \"message\": (f\"the call with Idempotency-Key {_idem_display(key)!r} completed and was charged, \"\n                          f\"but its response could not be read back. GET /calls/{replay.call_ref}/result may \"\n                          \"still have it; send a new key to call again.\")}\n    return IdempotentReplay(body=json.dumps({\"detail\": detail}, separators=(\",\", \":\")).encode(),\n                            status_code=410, media_type=\"application/json\",\n                            charged_micro=replay.charged_micro, call_ref=replay.call_ref)\n\n\nasync def _release_idempotent_claim(claim: tuple[int, str, str] | None) -> None:\n    \"\"\"Drop a claim this request took and never completed, so the label is usable again at once.\n\n    Does nothing when there is no claim, which is every request that sent no key. Never raises: this\n    runs while an error is already being returned.\n    \"\"\"\n    if not claim:\n        return\n    membership_id, key, call_ref = claim\n\n    async def _drop() -> None:\n        async with session_maker() as db:\n            await db.execute(delete(IdempotentCall).where(\n                *_owned(membership_id, key, call_ref), IdempotentCall.status == \"pending\"))\n            await db.commit()\n\n    try:\n        await _with_pool_retry(_drop)\n    except Exception as exc:\n        logging.getLogger(\"treg.idempotency\").error(\n            \"could not release idempotency claim %s: %s\", key, exc, exc_info=True)\n\n\nasync def _claim_idempotent(key: str, fingerprint: str, rest: str, caller: Caller,\n                            db: AsyncSession, *, call_ref: str) -> bool:\n    \"\"\"Take the label for this caller, or report that somebody else already has it.\n\n    The pending row IS the lock. It goes in before the upstream call, so a concurrent retry loses the\n    insert on `(membership_id, key)` and is told to wait rather than duplicating the spend. It\n    carries the owner's `call_ref` from the start: every later write is fenced on it, and a stale\n    claim is resolved from that call's money.\n    \"\"\"\n    # Opportunistically release this caller's expired labels. The hourly worker additionally\n    # cleans completed answers for callers who never return; see prune_expired_idempotency.\n    #\n    # The label being reused is freed by `_replay_idempotent`, which deletes that one expired row\n    # before this runs; this sweep reclaims the caller's OTHER expired labels. It deletes only rows\n    # it can lock (SKIP LOCKED, bounded): a concurrent batch from one member would otherwise queue\n    # every request on the same expired rows. A row skipped is one a concurrent request is deleting\n    # or finishing; the next call sweeps whatever is left.\n    expired = (select(IdempotentCall.id).where(\n        IdempotentCall.membership_id == caller.membership.id,\n        IdempotentCall.expires_at < datetime.now(timezone.utc).replace(tzinfo=None))\n        .limit(IDEMPOTENCY_SWEEP_BATCH).with_for_update(skip_locked=True))\n    await db.execute(delete(IdempotentCall).where(IdempotentCall.id.in_(expired)))\n\n    row = IdempotentCall(\n        org_id=caller.org_id, membership_id=caller.membership.id, key=key, call_ref=call_ref,\n        request_fingerprint=fingerprint, endpoint_id=rest[:200], status=\"pending\",\n        expires_at=datetime.now(timezone.utc).replace(tzinfo=None)\n        + timedelta(seconds=IDEMPOTENCY_WINDOW_S))\n    db.add(row)\n    try:\n        await db.commit()\n    except IntegrityError:\n        await db.rollback()\n        return False\n    return True\n\n\ndef _too_large_note(key: str, call_ref: str, charged_micro: int, size: int) -> tuple[bytes, int, str]:\n    \"\"\"What a retry gets instead of an answer over the archive's size limit (`archive_max_body_bytes`).\n\n    The caller already received the full answer; only the retry copy is dropped. A 410, never a new\n    run: running the key again is the double charge this table prevents. Without the limit every\n    body was kept whole for 24 h, however large.\n    \"\"\"\n    detail = {\"error\": \"idempotency_response_too_large\", \"call_id\": call_ref, \"charged_micro\": charged_micro,\n              \"size_bytes\": size,\n              \"message\": (f\"the call with Idempotency-Key {_idem_display(key)!r} completed and was charged, \"\n                          f\"but its response ({size} bytes) is over treg's retry size limit, so it was \"\n                          \"not kept for replay. Send a new key to call again.\")}\n    return json.dumps({\"detail\": detail}, separators=(\",\", \":\")).encode(), 410, \"application/json\"\n\n\ndef _not_retained_note(call_ref: str, charged_micro: int) -> tuple[bytes, int, str]:\n    \"\"\"Keep the claim and charge when an upstream response cannot be retained.\"\"\"\n    detail = {\"error\": \"idempotency_response_not_retained\", \"call_id\": call_ref,\n              \"charged_micro\": charged_micro,\n              \"message\": \"the provider response was not retained for replay. Send a new key to call again.\"}\n    return json.dumps({\"detail\": detail}, separators=(\",\", \":\")).encode(), 410, \"application/json\"\n\n\nasync def _store_idempotent(key: str, caller: Caller, *, status_code: int, body: bytes,\n                            media_type: str, charged_micro: int, metered: bool,\n                            call_ref: str, terminal: bool = False,\n                            response_retention_forbidden: bool = False) -> None:\n    \"\"\"Remember a metered success or an explicitly terminal, partially charged routed failure.\n\n    Metered calls keep their answer. A team calling on its OWN key is billed by the provider, not\n    by us, so its ordinary response is not kept. When retention is forbidden, every successful\n    call keeps a 410 receipt instead of a response body, including an own-key call. Ordinary\n    failures are not retained, because no charge landed and the caller should be free to retry.\n    A routed waterfall may already have settled paid children before its terminal failure;\n    `terminal=True` retains that exact failure so a retry cannot repeat those charges.\n\n    Anything else drops the claim, which frees the label immediately rather than making the caller\n    wait out the window before they can try again.\n\n    Never raises: the caller already has their answer, and a bookkeeping failure must not turn a\n    served call into a 500. Its own session, because the request's may be mid-rollback. Fenced on\n    `call_ref`: a claim another call took over is left alone.\n    \"\"\"\n    keep = (metered or response_retention_forbidden) and (200 <= status_code < 300 or terminal)\n    owned = (*_owned(caller.membership.id, key, call_ref), IdempotentCall.status == \"pending\")\n    if keep and response_retention_forbidden:\n        body, status_code, media_type = _not_retained_note(call_ref, charged_micro)\n    elif keep and len(body) > get_settings().archive_max_body_bytes:\n        body, status_code, media_type = _too_large_note(key, call_ref, charged_micro, len(body))\n\n    async def _write() -> None:\n        async with session_maker() as db:\n            if not keep:\n                await db.execute(delete(IdempotentCall).where(*owned))\n            else:\n                await db.execute(update(IdempotentCall).where(*owned).values(\n                    status=\"done\", response_status=status_code, response_body=body,\n                    response_media_type=media_type or \"application/json\",\n                    charged_micro=charged_micro))\n            await db.commit()\n\n    try:\n        await _with_pool_retry(_write)\n    except Exception as exc:\n        logging.getLogger(\"treg.idempotency\").error(\n            \"could not record idempotency key %s: %s\", key, exc, exc_info=True)\n\n\n@dataclass(frozen=True)\nclass IdempotencyPruneResult:\n    cutoff: datetime\n    upper_id: int\n    eligible: int\n    deleted: int\n    batches: int\n    complete: bool\n    page_timeouts: int = 0\n\n\n_PAGE_TIMEOUT_S = 60\n_DELETE_TIMEOUT_S = 15\n\n\nasync def prune_expired_idempotency(*, batch_size: int = 200, pause_s: float = 0.25,\n                                   max_batches: int = 10000, dry_run: bool = False,\n                                   make_session=session_maker) -> IdempotencyPruneResult:\n    \"\"\"Remove only completed, expired answers, with a fixed window and bounded transactions.\n\n    Page IDs first, then filter the DELETE: filtering before LIMIT can walk the entire cold\n    history to find one expired row. The primary-key cursor bounds each page without a migration.\n    Concurrent caller cleanup is harmless: the DELETE repeats the eligibility predicate.\n    Pending claims and responses valid at the start of the sweep cannot be removed.\n\n    **Timeout resilience.** After a large first prune (or any mass delete), dead tuple bloat can\n    make even a bounded page SELECT slow: the executor must skip invisible rows to find N visible\n    ones. The page SELECT uses a 60s timeout; if that expires, the cursor advances by batch_size\n    (the page is skipped, not retried) and the sweep continues. The next cron run starts from the\n    front, so skipped pages are retried on fresh autovacuum state. Any skipped page makes the\n    result incomplete, even when later pages succeed; three consecutive timeouts stop traversal.\n\n    Ops note: after a large initial prune, run `VACUUM (ANALYZE) idempotentcall` once. Autovacuum\n    handles routine churn; manual vacuum is only needed after an abnormally large delete ratio.\n    \"\"\"\n    if not 1 <= batch_size <= 1000 or not 1 <= max_batches <= 10000:\n        raise ValueError(\"batch_size must be 1..1000 and max_batches must be 1..10000\")\n    if not 0 <= pause_s <= 60:\n        raise ValueError(\"pause_s must be 0..60\")\n    log = logging.getLogger(\"treg.idempotency\")\n\n    async def bound_page(db):\n        if db.bind.dialect.name == \"postgresql\":\n            await db.execute(text(\"SET LOCAL lock_timeout = '1s'\"))\n            await db.execute(text(f\"SET LOCAL statement_timeout = '{_PAGE_TIMEOUT_S}s'\"))\n\n    async def bound_delete(db):\n        if db.bind.dialect.name == \"postgresql\":\n            await db.execute(text(\"SET LOCAL lock_timeout = '1s'\"))\n            await db.execute(text(f\"SET LOCAL statement_timeout = '{_DELETE_TIMEOUT_S}s'\"))\n\n    async with make_session() as db:\n        await bound_page(db)\n        cutoff = (await db.scalar(select(func.current_timestamp()))).replace(tzinfo=None)\n        upper_id = (await db.scalar(select(func.max(IdempotentCall.id)))) or 0\n        eligible_where = (\n            IdempotentCall.status == \"done\",\n            IdempotentCall.expires_at < cutoff,\n            IdempotentCall.id <= upper_id,\n        )\n    cursor = eligible = deleted = batches = page_timeouts = 0\n    consecutive_timeouts = 0\n    complete = False\n    while batches < max_batches:\n        rows = None\n        try:\n            async with make_session() as db:\n                await bound_page(db)\n                rows = (await db.execute(select(\n                    IdempotentCall.id, IdempotentCall.status, IdempotentCall.expires_at,\n                ).where(\n                    IdempotentCall.id <= upper_id, IdempotentCall.id > cursor,\n                ).order_by(IdempotentCall.id).limit(batch_size))).all()\n        except Exception as exc:\n            is_timeout = \"statement timeout\" in str(exc).lower() or \"QueryCanceledError\" in type(exc).__name__\n            if is_timeout:\n                page_timeouts += 1\n                consecutive_timeouts += 1\n                log.warning(\n                    \"idempotency prune page timeout: cursor=%d batch_size=%d consecutive=%d (advancing)\",\n                    cursor, batch_size, consecutive_timeouts)\n                cursor += batch_size\n                batches += 1\n                if cursor >= upper_id:\n                    complete = True\n                    break\n                if consecutive_timeouts >= 3:\n                    log.error(\"idempotency prune: %d consecutive page timeouts, stopping\", consecutive_timeouts)\n                    break\n                await asyncio.sleep(pause_s)\n                continue\n            raise\n        consecutive_timeouts = 0\n        if not rows:\n            complete = True\n            break\n        ids = [row.id for row in rows if row.status == \"done\" and row.expires_at < cutoff]\n        eligible += len(ids)\n        if ids and not dry_run:\n            async with make_session() as db:\n                await bound_delete(db)\n                removed = (await db.execute(delete(IdempotentCall).where(\n                    *eligible_where, IdempotentCall.id.in_(ids),\n                ).returning(IdempotentCall.id))).all()\n                await db.commit()\n                deleted += len(removed)\n        cursor = rows[-1].id\n        batches += 1\n        complete = len(rows) < batch_size or cursor == upper_id\n        if batches % 50 == 0:\n            log.info(\n                \"idempotency prune: batches=%d deleted=%d cursor=%d timeouts=%d\",\n                batches, deleted, cursor, page_timeouts)\n        if complete:\n            break\n        await asyncio.sleep(pause_s)\n\n    return IdempotencyPruneResult(\n        cutoff, upper_id, eligible, deleted, batches, complete and page_timeouts == 0, page_timeouts,\n    )\n\n\n@dataclass(frozen=True)\nclass IdempotencyTrimResult:\n    cutoff: datetime\n    upper_id: int\n    examined: int\n    trimmed: int\n    bytes_freed: int\n    batches: int\n    complete: bool\n\n\nasync def trim_archived_answers(*, batch_size: int = 200, pause_s: float = 0.25,\n                                max_batches: int = 10000, min_age_s: int = 600, dry_run: bool = False,\n                                make_session=session_maker) -> IdempotencyTrimResult:\n    \"\"\"Drop a live retry row's own copy of an answer the archive holds byte for byte.\n\n    Without this the same answer is stored twice, once per table, for a day. A row qualifies when its call's `CallRecord`\n    names an archive answer, that answer still carries its bytes (`archive.bytes_on_file`), and the\n    sha256 of the row's own bytes equals it. Only then is `response_body` cleared and the archive\n    entry named; a replay reads it from there (`_archived_answer`), and a 410 answers if it is gone.\n\n    `min_age_s`: the archive records a moment after the call and can shed a recording under load,\n    so a row is looked at only once it is ten minutes old. Paged like `prune_expired_idempotency`:\n    a fixed upper id, id pages without bodies first, bodies read only for qualifying rows.\n    \"\"\"\n    if not 1 <= batch_size <= 1000 or not 1 <= max_batches <= 10000:\n        raise ValueError(\"batch_size must be 1..1000 and max_batches must be 1..10000\")\n    log = logging.getLogger(\"treg.idempotency\")\n\n    async def bound(db):\n        if db.bind.dialect.name == \"postgresql\":\n            await db.execute(text(\"SET LOCAL lock_timeout = '1s'\"))\n            await db.execute(text(f\"SET LOCAL statement_timeout = '{_PAGE_TIMEOUT_S}s'\"))\n\n    async with make_session() as db:\n        await bound(db)\n        cutoff = (await db.scalar(select(func.current_timestamp()))).replace(tzinfo=None)\n        upper_id = (await db.scalar(select(func.max(IdempotentCall.id)))) or 0\n    settled_before = cutoff - timedelta(seconds=min_age_s)\n    cursor = examined = trimmed = freed = batches = 0\n    complete = False\n    while batches < max_batches:\n        async with make_session() as db:\n            await bound(db)\n            page = (await db.execute(select(\n                IdempotentCall.id, IdempotentCall.org_id, IdempotentCall.call_ref, IdempotentCall.status,\n                IdempotentCall.response_status, IdempotentCall.created_at, IdempotentCall.expires_at,\n                IdempotentCall.archive_content_hash, IdempotentCall.response_body.is_not(None).label(\"has_body\"),\n            ).where(IdempotentCall.id > cursor, IdempotentCall.id <= upper_id)\n              .order_by(IdempotentCall.id).limit(batch_size))).all()\n            if not page:\n                complete = True\n                break\n            rows = [r for r in page if r.status == \"done\" and r.has_body and r.call_ref\n                    and r.archive_content_hash is None and 200 <= (r.response_status or 0) < 300\n                    and r.created_at < settled_before and r.expires_at >= cutoff]\n            examined += len(rows)\n            links = {}\n            if rows:\n                links = {(c.org_id, c.call_ref): (c.archive_key_hash, c.archive_content_hash)\n                         for c in (await db.execute(select(\n                             CallRecord.org_id, CallRecord.call_ref, CallRecord.archive_key_hash,\n                             CallRecord.archive_content_hash,\n                         ).where(CallRecord.call_ref.in_({r.call_ref for r in rows}),\n                                 CallRecord.archive_content_hash.is_not(None)))).all()}\n            wanted = {r.id: links[(r.org_id, r.call_ref)] for r in rows if (r.org_id, r.call_ref) in links}\n            on_file = await archive.bytes_on_file(db, set(wanted.values()))\n            wanted = {i: pair for i, pair in wanted.items() if pair in on_file}\n            if wanted:\n                bodies = (await db.execute(select(IdempotentCall.id, IdempotentCall.response_body)\n                                           .where(IdempotentCall.id.in_(wanted)))).all()\n                same = [(b.id, len(b.response_body)) for b in bodies\n                        if b.response_body is not None and archive.content_hash(b.response_body) == wanted[b.id][1]]\n                for row_id, size in same:\n                    if dry_run:\n                        trimmed, freed = trimmed + 1, freed + size\n                        continue\n                    key_hash, body_hash = wanted[row_id]\n                    done = (await db.execute(update(IdempotentCall).where(\n                        IdempotentCall.id == row_id, IdempotentCall.status == \"done\",\n                        IdempotentCall.response_body.is_not(None), IdempotentCall.archive_content_hash.is_(None),\n                    ).values(response_body=None, archive_key_hash=key_hash, archive_content_hash=body_hash)\n                    .execution_options(synchronize_session=False))).rowcount\n                    trimmed, freed = trimmed + done, freed + (size if done else 0)\n                await db.commit()\n        cursor = page[-1].id\n        batches += 1\n        if len(page) < batch_size or cursor >= upper_id:\n            complete = True\n            break\n        if batches % 50 == 0:\n            log.info(\"idempotency trim: batches=%d trimmed=%d freed=%d cursor=%d\", batches, trimmed, freed, cursor)\n        await asyncio.sleep(pause_s)\n    return IdempotencyTrimResult(cutoff, upper_id, examined, trimmed, freed, batches, complete)\n"
    },
    {
      "path": "dsh/cordis.patch.yml",
      "content": "# The layer this bundle contributes to a dsh profile that lists it.\n#\n# Two rows, and the second one is the interesting one.\n#\n# `treg-skill` publishes the packaged SKILL.md on `ctx.skills`. It costs nothing\n# and needs no token, so it is always on.\n#\n# `treg-mcp` connects the hosted MCP server and registers its tools as\n# `mcp__treg__*`. It is DISABLED until `TREG_TOKEN` is in the environment,\n# because dsh's MCP client sends a static header and runs no OAuth, so a row\n# registered without a token is five always-on tools that 401 on every call.\n# Set the token and restart dsh and the tools appear; until then the skill\n# walks the human through getting one.\n#\n# Row shape and the `!!js` evaluation: dsh's own dsh-base patch uses the same\n# `disabled: !!js ...` form for its platform-specific rows.\n# https://github.com/deepseek-ai/deepseek-harness/blob/master/docs/user/develop/basic/publish.md\n\n- insert:\n    - id: treg-skill\n      name: treg-dsh\n\n    # The expression may NOT begin with `!`: YAML reads a second `!` after the\n    # `!!js` tag as another tag property and the whole file fails to parse\n    # (\"duplication of a tag property\"), taking the profile down with it.\n    - id: treg-mcp\n      name: '@deepseek-ai/dsh-mcp-client'\n      disabled: !!js (process.env.TREG_TOKEN ?? '') === ''\n      config:\n        serverName: treg\n        transport: streamable-http\n        url: https://treg.to/mcp/\n        headers:\n          Authorization: !!js '`Bearer ${process.env.TREG_TOKEN}`'\n"
    },
